def _compute_invoices_count(self):
    tx_data = {}
    if self.ids:
        self.env.cr.execute(
            '''
            SELECT transaction_id, count(invoice_id)
            FROM account_invoice_transaction_rel
            WHERE transaction_id IN %s
            GROUP BY transaction_id
            ''',
            [tuple(self.ids)]
        )
        tx_data = dict(self.env.cr.fetchall())  # {id: count}
    for tx in self:
        tx.invoices_count = tx_data.get(tx.id, 0)

def _log_message_on_linked_documents(self, message):
    """ Log a message on the payment and the invoices linked to the transaction.

    For a module to implement payments and link documents to a transaction, it must override
    this method and call super, then log the message on documents linked to the transaction.

    Note: self.ensure_one()

    :param str message: The message to be logged
    :return: None
    """
    self.ensure_one()
    if self.env.uid == SUPERUSER_ID or self.env.context.get('payment_backend_action'):
        author = self.env.user.partner_id
    else:
        author = self.partner_id
    if self.source_transaction_id:
        for invoice in self.source_transaction_id.invoice_ids:
            invoice.message_post(body=message, author_id=author.id)
        payment_id = self.source_transaction_id.payment_id
        if payment_id:
            payment_id.message_post(body=message, author_id=author.id)
    for invoice in self._get_invoices_to_notify():
        invoice.message_post(body=message, author_id=author.id)

def _get_invoices_to_notify(self):
    """ Return the invoices on which to log payment-related messages. """
    return self.invoice_ids

def _compute_sale_order_reference(self, order):
    self.ensure_one()
    if self.provider_id.so_reference_type == "so_name":
        order_reference = order.name
    elif self.provider_id.so_reference_type == "partner":
        identification_number = order.partner_id.id
        order_reference = "%s/%s" % ("CUST", str(identification_number % 97).rjust(2, "0"))
    else:
        # self.provider_id.so_reference_type is empty
        order_reference = False

    invoice_journal = self.env["account.journal"].search(
        [("type", "=", "sale"), ("company_id", "=", self.company_id.id)], limit=1
    )
    if invoice_journal:
        order_reference = invoice_journal._process_reference_for_sale_order(order_reference)

    return order_reference

def _compute_sale_order_ids_nbr(self):
    for trans in self:
        trans.sale_order_ids_nbr = len(trans.sale_order_ids)

def _post_process(self):
    """Override of `payment` to add Sales-specific logic to the post-processing.

    In particular, for pending transactions, we send the quotation by email; for authorized
    transactions, we confirm the quotation; for confirmed transactions, we automatically confirm
    the quotation and generate invoices.
    """
    for pending_tx in self.filtered(lambda tx: tx.state == "pending"):
        super(PaymentTransaction, pending_tx)._post_process()
        sales_orders = pending_tx.sale_order_ids.filtered(
            lambda so: so.state in ["draft", "sent"]
        )

        sales_orders.filtered(lambda so: so.state == "draft").with_context(
            tracking_disable=True
        ).action_quotation_sent()

        if pending_tx.provider_id.code == "custom":
            for order in pending_tx.sale_order_ids:
                order.reference = pending_tx._compute_sale_order_reference(order)

        if pending_tx.operation == "validation":
            continue
        # Send the payment status email.
        # The transactions are manually cached while in a sudoed environment to prevent an
        # AccessError: In some circumstances, sending the mail would generate the report assets
        # during the rendering of the mail body, causing a cursor commit, a flush, and forcing
        # the re-computation of the pending computed fields of the `mail.compose.message`,
        # including part of the template. Since that template reads the order's transactions and
        # the re-computation of the field is not done with the same environment, reading fields
        # that were not already available in the cache could trigger an AccessError (e.g., if
        # the payment was initiated by a public user).
        sales_orders.mapped("transaction_ids")
        sales_orders._send_payment_succeeded_for_order_mail()

    for authorized_tx in self.filtered(lambda tx: tx.state == "authorized"):
        super(PaymentTransaction, authorized_tx)._post_process()
        confirmed_orders = authorized_tx._check_amount_and_confirm_order()
        if authorized_tx.operation == "validation":
            continue
        if remaining_orders := (authorized_tx.sale_order_ids - confirmed_orders):
            remaining_orders._send_payment_succeeded_for_order_mail()

    super(
        PaymentTransaction,
        self.filtered(lambda tx: tx.state not in ["pending", "authorized", "done"]),
    )._post_process()

    for done_tx in self.filtered(lambda tx: tx.state == "done"):
        if done_tx.operation != "validation":
            confirmed_orders = done_tx._check_amount_and_confirm_order()
            (done_tx.sale_order_ids - confirmed_orders)._send_payment_succeeded_for_order_mail()

        auto_invoice = done_tx.company_id.sale_automatic_invoice
        if auto_invoice:
            # Invoice the sales orders of confirmed transactions instead of only confirmed
            # orders to create the invoice even if only a partial payment was made.
            done_tx._invoice_sale_orders()
        super(PaymentTransaction, done_tx)._post_process()  # Post the invoices.
        if auto_invoice and not self.env.context.get("skip_sale_auto_invoice_send"):
            if self.env["ir.config_parameter"].sudo().get_bool("sale.async_emails") and (
                send_invoice_cron := self.env.ref(
                    "sale.send_invoice_cron", raise_if_not_found=False
                )
            ):
                send_invoice_cron._trigger()
            else:
                self._send_invoice()

def _log_message_on_linked_documents(self, message):
    """Override of payment to log a message on the sales orders linked to the transaction.

    Note: self.ensure_one()

    :param str message: The message to be logged
    :return: None
    """
    super()._log_message_on_linked_documents(message)
    if self.env.uid == SUPERUSER_ID or self.env.context.get("payment_backend_action"):
        author = self.env.user.partner_id
    else:
        author = self.partner_id
    for order in self.sale_order_ids or self.source_transaction_id.sale_order_ids:
        order.message_post(body=message, author_id=author.id)

def _send_invoice(self):
    # Send messages as OdooBot so that
    #   * logged in users receive the invoice
    #   * the mail and notifications are not sent by the public user
    for tx in self.with_user(SUPERUSER_ID):
        tx = tx.with_company(tx.company_id).with_context(company_id=tx.company_id.id)
        invoice_to_send = tx.invoice_ids.filtered(
            lambda i: not i.is_move_sent and i.state == "posted" and i._is_ready_to_be_sent()
        )

        send_context = {"allow_raising": False, "allow_fallback_pdf": True}
        default_template_param = (
            self
            .env["ir.config_parameter"]
            .sudo()
            .get_int("sale.default_invoice_email_template")
        )
        if default_template_param:
            mail_template = self.env["mail.template"].sudo().browse(default_template_param)
            if mail_template.exists():
                send_context["mail_template"] = mail_template

        tx.env['account.move.send']._generate_and_send_invoices_post_commit(invoice_to_send, **send_context)

def action_view_sales_orders(self):
    action = {
        "name": self.env._("Sales Order(s)"),
        "type": "ir.actions.act_window",
        "res_model": "sale.order",
        "target": "current",
    }
    sale_order_ids = self.sale_order_ids.ids
    if len(sale_order_ids) == 1:
        action["res_id"] = sale_order_ids[0]
        action["view_mode"] = "form"
    else:
        action["view_mode"] = "list,form"
        action["domain"] = [("id", "in", sale_order_ids)]
    return action

def on_change_with_process_method(self, name=None):
    if self.journal:
        return self.journal.process_method

def preprocess_values(cls, mode, values):
    pool = Pool()
    Configuration = pool.get('account.configuration')
    values = super().preprocess_values(mode, values)
    if mode == 'create' and not values.get('number'):
        configuration = Configuration(1)
        company_id = values.get('company', cls.default_company())
        if company_id is not None:
            if sequence := configuration.get_multivalue(
                    'payment_group_sequence', company=company_id):
                values['number'] = sequence.get()
    return values

def amount_line_paid(self):
    if self.state != 'failed':
        if self.line.second_currency:
            payment_amount = abs(self.line.amount_second_currency)
        else:
            payment_amount = abs(self.line.credit - self.line.debit)
        return max(min(self.amount, payment_amount), 0)
    return Decimal(0)

def order_number(cls, tables):
    table, _ = tables[None]
    return [CharLength(table.number), table.number]

def on_change_with_reference(self):
    if (reference := self.reference) and (type := self.reference_type):
        reference = getattr(self, f'_format_reference_{type}')(reference)
    return reference

def _format_reference_creditor_reference(cls, reference):
    try:
        return iso11649.format(reference)
    except stdnum.exceptions.ValidationError:
        return reference

def reference_used(self):
    reference = self.reference
    if not reference and self.line and self.line.move_origin:
        reference = getattr(self.line.move_origin, 'rec_name', None)
    return reference

def order_amount(cls, tables):
    table, _ = tables[None]
    context = Transaction().context
    column = cls.amount.sql_column(tables, cls)
    if isinstance(context.get('amount_order'), Decimal):
        return [Abs(column - abs(context['amount_order']))]
    else:
        return [column]

def on_change_line(self):
    if self.line:
        self.date = self.line.maturity_date
        self.amount = self.line.payment_amount

def _get_origin(cls):
    'Return list of Model names for origin Reference'
    return []

def on_change_with_process_method(self, name=None):
    if self.journal:
        return self.journal.process_method

def chat_language(self, audience='internal'):
    language = super().chat_language(audience=audience)
    if audience == 'public':
        language = self.party.lang.code if self.party.lang else None
    return language

def copy(cls, payments, default=None):
    if default is None:
        default = {}
    else:
        default = default.copy()
    default.setdefault('number', None)
    default.setdefault('reference')
    default.setdefault('reference_type')
    default.setdefault('group', None)
    default.setdefault('approved_by')
    default.setdefault('succeeded_by')
    default.setdefault('failed_by')
    return super().copy(payments, default=default)

def preprocess_values(cls, mode, values):
    pool = Pool()
    Configuration = pool.get('account.configuration')
    values = super().preprocess_values(mode, values)
    if mode == 'create' and not values.get('number'):
        configuration = Configuration(1)
        company_id = values.get('company', cls.default_company())
        if company_id is not None:
            if sequence := configuration.get_multivalue(
                    'payment_sequence', company=company_id):
                values['number'] = sequence.get()
    return values

def check_modification(cls, mode, payments, values=None, external=False):
    super().check_modification(
        mode, payments, values=values, external=external)
    if mode == 'delete':
        for payment in payments:
            if payment.state != 'draft':
                raise AccessError(gettext(
                        'account_payment.msg_payment_delete_draft',
                        payment=payment.rec_name))

def on_modification(cls, mode, payments, field_names=None):
    pool = Pool()
    Line = pool.get('account.move.line')
    super().on_modification(mode, payments, field_names=field_names)
    if mode in {'create', 'write'}:
        if field_names is None or 'line' in field_names:
            if lines := Line.browse({p.line for p in payments if p.line}):
                Line.set_payment_amount(lines)

def on_write(cls, payments, values):
    pool = Pool()
    Line = pool.get('account.move.line')
    callback = super().on_write(payments, values)
    if values.keys() & {'line', 'amount', 'state'}:
        if lines := Line.browse({p.line for p in payments if p.line}):
            callback.append(lambda: Line.set_payment_amount(lines))
    return callback

def validate_fields(cls, payments, field_names):
    super().validate_fields(payments, field_names)
    cls.check_reference(payments, field_names)

def check_reference(cls, payments, field_names):
    if field_names and not (field_names & {'reference', 'reference_type'}):
        return

    for payment in payments:
        if type := payment.reference_type:
            method = getattr(cls, f'_check_reference_{type}')
            if not method(payment):
                reference = payment.reference
                type = payment.reference_type_string
                raise PaymentValidationError(gettext(
                        'account_payment.msg_payment_reference_invalid',
                        type=type,
                        reference=reference,
                        payment=payment.rec_name))

def process(cls, payments, group=None):
    if payments:
        if group:
            group = group()
            cls.write(payments, {
                    'group': group.id,
                    })
        # Set state before calling process method
        # as it may set a different state directly
        cls.proceed(payments)
        if group:
            getattr(group, f'process_{group.process_method}')()
        else:
            for payment in payments:
                getattr(payment, f'process_{payment.process_method}')()
        return group

def proceed(cls, payments):
    cls._check_reconciled(
        [p for p in payments if p.state not in {'succeeded', 'failed'}])

def _check_reconciled(cls, payments):
    pool = Pool()
    Warning = pool.get('res.user.warning')
    for payment in payments:
        if payment.line and payment.line.reconciliation:
            key = Warning.format('submit_reconciled', [payment])
            if Warning.check(key):
                raise ReconciledWarning(
                    key, gettext(
                        'account_payment.msg_payment_reconciled',
                        payment=payment.rec_name,
                        line=payment.line.rec_name))

def submit(cls, payments):
    super().submit(payments)
    cls._check_payment_means(payments)

def _check_payment_means(cls, payments):
    pool = Pool()
    Warning = pool.get('res.user.warning')
    Invoice = pool.get('account.invoice')
    for payment in payments:
        if (payment.line
                and isinstance(payment.line.move.origin, Invoice)):
            invoice = payment.line.move.origin
            if invoice.payment_means:
                if not any(
                        mean.is_valid_with_payment(payment)
                        for mean in invoice.payment_means):
                    key = Warning.format('payment_means', [payment])
                    if Warning.check(key):
                        raise PaymentMeanWarning(
                            key, gettext(
                                'account_payment.msg_payment_means',
                                journal=payment.journal.rec_name,
                                payment=payment.rec_name,
                                invoice=invoice.rec_name))

def _group_payment_key(self, payment):
    return (
        ('company', payment.company),
        ('journal', payment.journal),
        ('kind', payment.kind),
        )

def _new_group(self, values):
    pool = Pool()
    Group = pool.get('account.payment.group')
    return Group(**values)

def on_change_company(self):
    company_party = self.on_change_with_company_party()
    if self.company:
        if self.tax_identifier:
            if self.tax_identifier.party != company_party:
                self.tax_identifier = None
    else:
        self.tax_identifier = None

def on_change_type(self):
    self.set_journal()
    self.on_change_party()

def _journal_types(cls, invoice_type):
    if invoice_type == 'out':
        return ['revenue']
    else:
        return ['expense']

def set_journal(self, pattern=None):
    pool = Pool()
    Journal = pool.get('account.journal')
    pattern = pattern.copy() if pattern is not None else {}
    pattern.setdefault('type', {
            'out': 'revenue',
            'in': 'expense',
            }.get(self.type))
    self.journal = Journal.find(pattern)

def order_accounting_date(cls, tables):
    table, _ = tables[None]
    return [Coalesce(table.accounting_date, table.invoice_date)]

def on_change_party(self):
    if self.party:
        self.invoice_address = self.party.address_get(type='invoice')
        self.party_tax_identifier = self.party.tax_identifier
        if self.type == 'out':
            self.account = self.party.account_receivable_used
            self.payment_term = self.party.customer_payment_term
        elif self.type == 'in':
            self.account = self.party.account_payable_used
            self.payment_term = self.party.supplier_payment_term
    else:
        self.invoice_address = None
        self.account = None
        self.payment_term = None
        self.party_tax_identifier = None
    self._update_account()

def _update_account(self):
    "Update account to current account"
    if self.account:
        account = self.account.current(
            date=self.accounting_date or self.invoice_date)
        if account != self.account:
            self.account = account

def on_change_with_currency_date(self, name=None):
    Date = Pool().get('ir.date')
    if self.company:
        company_id = self.company.id
    else:
        company_id = Transaction().context.get('company')
    with Transaction().set_context(company=company_id):
        return self.invoice_date or Date.today()

def on_change_with_supplier_payment_reference(self):
    reference = self.supplier_payment_reference
    if reference and (type := self.supplier_payment_reference_type):
        reference = getattr(
            self, f'_format_supplier_payment_reference_{type}')(reference)
    return reference

def _format_supplier_payment_reference_creditor_reference(cls, reference):
    try:
        return iso11649.format(reference)
    except stdnum.exceptions.ValidationError:
        return reference

def get_customer_payment_reference(self, name):
    return self.format_customer_payment_reference(
        self._customer_payment_reference_type())

def search_customer_payment_reference(cls, name, clause):
    _, operator, value = clause[:3]
    if operator == '=':
        return ['OR', *cls._search_customer_payment_reference(value)]
    else:
        return []

def _search_customer_payment_reference(cls, value):
    if iso11649.is_valid(value):
        yield ('number_alnum', '=', value[4:])

def _customer_payment_reference_number_alnum(self, source):
    if source == 'invoice':
        return self.number_alnum
    elif source == 'party':
        return self.party.code_alnum

def _customer_payment_reference_number_digit(self, source):
    if source == 'invoice':
        return self.number_digit
    elif source == 'party':
        return self.party.code_digit

def _format_customer_payment_reference_creditor_reference(self, source):
    number = self._customer_payment_reference_number_alnum(source)
    if number:
        number = number[-25:].upper()
        check_digits = iso7064.mod_97_10.calc_check_digits(f'{number}RF')
        return iso11649.format(f'RF{check_digits}{number}')

def on_change_with_party_lang(self, name=None):
    Config = Pool().get('ir.configuration')
    if self.party and self.party.lang:
        return self.party.lang.code
    return Config.get_language()

def get_type_name(cls, invoices, name):
    type_names = {}
    type2name = {}
    for type, name in cls.fields_get(fields_names=['type']
            )['type']['selection']:
        type2name[type] = name
    for invoice in invoices:
        type_names[invoice.id] = type2name[invoice.type]
    return type_names

def _on_change_lines_taxes(self):
    pool = Pool()
    InvoiceTax = pool.get('account.invoice.tax')

    self.untaxed_amount = Decimal(0)
    self.tax_amount = Decimal(0)
    self.total_amount = Decimal(0)

    if self.lines:
        for line in self.lines:
            if getattr(line, 'type', '') == 'line':
                self.untaxed_amount += getattr(line, 'amount', 0) or 0
        computed_taxes = self._get_taxes()
    else:
        computed_taxes = {}

    def is_zero(amount):
        if self.currency:
            return self.currency.is_zero(amount)
        else:
            return amount == Decimal(0)

    tax_keys = set()
    taxes = list(self.taxes or [])
    for tax in (self.taxes or []):
        if tax.manual:
            self.tax_amount += tax.amount or Decimal(0)
            continue
        key = tax._key
        if (key not in computed_taxes) or (key in tax_keys):
            taxes.remove(tax)
            continue
        tax_keys.add(key)
        if not is_zero(
                computed_taxes[key].base - (tax.base or Decimal(0))):
            self.tax_amount += computed_taxes[key].amount
            tax.amount = computed_taxes[key].amount
            tax.base = computed_taxes[key].base
        else:
            self.tax_amount += tax.amount or Decimal(0)
    for key in computed_taxes:
        if key not in tax_keys:
            tax = computed_taxes[key].tax
            self.tax_amount += computed_taxes[key].amount
            value = InvoiceTax.default_get(
                list(InvoiceTax._fields.keys()), with_rec_name=False)
            value.update(computed_taxes[key].values())
            value['manual'] = False
            value['description'] = tax.description
            value['legal_notice'] = tax.legal_notice
            value['currency'] = self.currency
            invoice_tax = InvoiceTax(**value)
            if invoice_tax.tax:
                invoice_tax.sequence = invoice_tax.tax.sequence
            taxes.append(invoice_tax)
    self.taxes = taxes
    if self.currency:
        self.untaxed_amount = self.currency.round(self.untaxed_amount)
        self.tax_amount = self.currency.round(self.tax_amount)
    self.total_amount = self.untaxed_amount + self.tax_amount
    if self.currency:
        self.total_amount = self.currency.round(self.total_amount)

def get_reconciled(self, name):
    def get_reconciliation(line):
        if line.reconciliation and line.reconciliation.delegate_to:
            return get_reconciliation(line.reconciliation.delegate_to)
        else:
            return line.reconciliation
    reconciliations = list(map(get_reconciliation, self.lines_to_pay))
    if not reconciliations:
        return None
    elif not all(reconciliations):
        return None
    else:
        return max(r.date for r in reconciliations)

def get_allow_cancel(self, name):
    if self.state in {'draft', 'validated'}:
        return True
    if self.state == 'posted':
        return self.type == 'in' or self.company.cancel_invoice_out
    return False

def taxable_lines(self):
    taxable_lines = []
    for line in self.lines:
        if getattr(line, 'type', None) == 'line':
            taxable_lines.extend(line.taxable_lines)
    return taxable_lines

def _get_tax_context(self):
    context = {}
    if self.party_lang:
        context['language'] = self.party_lang
    if self.company:
        context['company'] = self.company.id
    return context

def update_taxes(cls, invoices, exception=False):
    Tax = Pool().get('account.invoice.tax')
    to_write = []
    with Tax.bulk_create(auto=False) as create, \
            Tax.bulk_delete(auto=False) as delete:
        for invoice in invoices:
            if invoice.state in ('posted', 'paid', 'cancelled'):
                continue
            computed_taxes = dict(invoice._compute_taxes())
            if not invoice.taxes:
                create.extend(computed_taxes.values())
            else:
                tax_keys = set()
                for tax in invoice.taxes:
                    if tax.manual:
                        continue
                    key = tax._key
                    if (key not in computed_taxes) or (key in tax_keys):
                        delete.push(tax)
                        continue
                    tax_keys.add(key)
                    if not invoice.currency.is_zero(
                            computed_taxes[key]['base'] - tax.base):
                        to_write.extend(([tax], computed_taxes[key]))
                for key in computed_taxes:
                    if key not in tax_keys:
                        create.push(computed_taxes[key])
            if exception and (create or delete or to_write):
                raise InvoiceTaxValidationError(
                    gettext('account_invoice.msg_invoice_tax_invalid',
                        invoice=invoice.rec_name))
    if to_write:
        Tax.write(*to_write)

def _get_move_line(self, date, amount):
    '''
    Return move line
    '''
    pool = Pool()
    Currency = pool.get('currency.currency')
    MoveLine = pool.get('account.move.line')
    line = MoveLine()
    if self.currency != self.company.currency:
        line.amount_second_currency = amount
        line.second_currency = self.currency
        with Transaction().set_context(date=self.currency_date):
            amount = Currency.compute(
                self.currency, amount, self.company.currency)
    else:
        line.amount_second_currency = None
        line.second_currency = None
    if amount >= 0:
        if self.type == 'out':
            line.debit, line.credit = amount, 0
        else:
            line.debit, line.credit = 0, amount
    else:
        if self.type == 'out':
            line.debit, line.credit = 0, -amount
        else:
            line.debit, line.credit = -amount, 0
    if line.amount_second_currency:
        line.amount_second_currency = (
            line.amount_second_currency.copy_sign(
                line.debit - line.credit))
    line.account = self.account
    if self.account.party_required:
        if self.alternative_payees:
            line.party, = self.alternative_payees
        else:
            line.party = self.party
    line.maturity_date = date
    line.description = self.description
    return line

def _number_sequence(self, pattern=None):
    "Returns the sequence and date to use for numbering"
    pool = Pool()
    Period = pool.get('account.period')

    if pattern is None:
        pattern = {}
    else:
        pattern = pattern.copy()

    accounting_date = self.accounting_date or self.invoice_date
    period = Period.find(
        self.company, date=accounting_date,
        test_state=self.type != 'in')

    fiscalyear = period.fiscalyear
    pattern.setdefault('company', self.company.id)
    pattern.setdefault('fiscalyear', fiscalyear.id)
    pattern.setdefault('period', period.id)

    for invoice_sequence in fiscalyear.invoice_sequences:
        if invoice_sequence.match(pattern):
            return getattr(
                invoice_sequence, self._sequence_field), accounting_date
    else:
        raise InvoiceNumberError(
            gettext('account_invoice.msg_invoice_no_sequence',
                invoice=self.rec_name,
                fiscalyear=fiscalyear.rec_name))

def _sequence_type(self):
    if (all(l.amount <= 0 for l in self.line_lines)
            and self.total_amount < 0):
        return 'credit_note'
    else:
        return 'invoice'

def _sequence_field(self):
    "Returns the field name of invoice_sequence to use"
    return f'{self.type}_{self.sequence_type}_sequence'

def get_tax_identifier(self, pattern=None):
    "Return the default computed tax identifier"
    pattern = pattern.copy() if pattern is not None else {}
    if self.invoice_address and self.invoice_address.country:
        pattern.setdefault('country', self.invoice_address.country.id)
    return self.company.get_tax_identifier(pattern)

def set_payment_means(cls, invoices):
    pool = Pool()
    PaymentMean = pool.get('account.invoice.payment.mean')
    PaymentMeanRule = pool.get('account.invoice.payment.mean.rule')
    payment_means = []
    rules = PaymentMeanRule.search([])
    for invoice in invoices:
        if invoice.type != 'out':
            continue
        if invoice.payment_means:
            continue
        pattern = PaymentMeanRule.pattern_from_invoice(invoice)
        for rule in rules:
            if rule.match(pattern):
                payment_mean = PaymentMean.from_rule(rule)
                payment_mean.invoice = invoice
                payment_means.append(payment_mean)
    PaymentMean.save(payment_means)

def is_modifiable(self):
    return not (self.state in {'posted', 'paid'}
        or (self.state == 'cancelled'
            and (self.move or self.cancel_move or self.number)))

def get_origins(self, name):
    return ', '.join(set(filter(None,
                (l.origin_name for l in self.line_lines))))

def get_origin_invoices(self, name):
    pool = Pool()
    InvoiceLine = pool.get('account.invoice.line')
    invoices = set()
    for line in self.lines:
        if isinstance(line.origin, InvoiceLine):
            invoices.add(line.origin.invoice.id)
    invoices.discard(self.id)
    return list(invoices)

def search_origin_invoices(cls, name, clause):
    return [('lines.origin.invoice' + clause[0][len(name):],
            *clause[1:3], 'account.invoice.line', *clause[3:])]

def chat_language(self, audience='internal'):
