    if audience == 'public':
        language = self.party_lang
    return language

def view_attributes(cls):
    pool = Pool()
    PaymentMean = pool.get('account.invoice.payment.mean')
    if not PaymentMean.get_instruments():
        payment_means = [
            ('/form//field[@name="payment_means"]', 'invisible', 1),
            ]
    else:
