def update_time_sheet(self, sales_invoice):
	for d in self.timesheets:
		if d.time_sheet:
			timesheet = frappe.get_doc("Timesheet", d.time_sheet)
			self.update_time_sheet_detail(timesheet, d, sales_invoice)
			timesheet.calculate_total_amounts()
			timesheet.calculate_percentage_billed()
			timesheet.flags.ignore_validate_update_after_submit = True
			timesheet.set_status()
			timesheet.db_update_all()

def update_billed_qty_in_scio(self):
	table = frappe.qb.DocType("Subcontracting Inward Order Received Item")
	sign = 1 if self._action == "submit" else -1
	data = {name: sign * qty for name, qty in self.get_scio_self_rm_stock_qty().items()}

	if data:
		case_expr = Case()
		for name, qty in data.items():
			case_expr = case_expr.when(table.name == name, table.billed_qty + qty)
		frappe.qb.update(table).set(table.billed_qty, case_expr).where(
			(table.name.isin(list(data.keys()))) & (table.docstatus == 1)
		).run()

def get_scio_self_rm_stock_qty(self):
	stock_qty = defaultdict(float)
	for item in self.items:
		if item.scio_detail:
			stock_qty[item.scio_detail] += flt(item.stock_qty)
	return stock_qty

def update_time_sheet_detail(self, timesheet, args, sales_invoice):
	for data in timesheet.time_logs:
		if (
			(self.project and args.timesheet_detail == data.name)
			or (not self.project and not data.sales_invoice and args.timesheet_detail == data.name)
			or (
				not sales_invoice
				and data.sales_invoice == self.name
				and args.timesheet_detail == data.name
			)
			or (
				self.is_return
				and self.return_against
				and data.sales_invoice
				and data.sales_invoice == self.return_against
				and not sales_invoice
				and args.timesheet_detail == data.name
			)
		):
			data.sales_invoice = sales_invoice

def set_account_for_mode_of_payment(self):
	for payment in self.payments:
		payment.account = get_bank_cash_account(payment.mode_of_payment, self.company).get("account")

def validate_time_sheets_are_submitted(self):
	# Note: This validation is skipped for return invoices
	# to allow returns to reference already-billed timesheet details
	listed = set()
	for data in self.timesheets:
		if data.timesheet_detail in listed:
			frappe.throw(
				_("Row {0}: The same time log of Timesheet {1} is added more than once").format(
					data.idx, frappe.bold(data.time_sheet)
				)
			)

		# Handle invoice duplication
		if data.time_sheet and data.timesheet_detail:
			listed.add(data.timesheet_detail)
			if sales_invoice := frappe.db.get_value(
				"Timesheet Detail", data.timesheet_detail, "sales_invoice"
			):
				frappe.throw(
					_("Row {0}: Sales Invoice {1} is already created for {2}").format(
						data.idx, frappe.bold(sales_invoice), frappe.bold(data.time_sheet)
					)
				)

		if data.time_sheet:
			status = frappe.db.get_value("Timesheet", data.time_sheet, "status")
			if status not in ["Submitted", "Payslip", "Partially Billed", "Billed"]:
				frappe.throw(
					_("Timesheet {0} cannot be invoiced in its current state").format(data.time_sheet)
				)

def set_pos_fields(self, for_validate=False):
	"""Set retail related fields from POS Profiles"""
	if cint(self.is_pos) != 1:
		return

	if not self.account_for_change_amount:
		self.account_for_change_amount = frappe.get_cached_value(
			"Company", self.company, "default_cash_account"
		)

	from erpnext.stock.get_item_details import (
		ItemDetailsCtx,
		get_pos_profile,
		get_pos_profile_item_details_,
	)

	if not self.pos_profile and not self.flags.ignore_pos_profile:
		pos_profile = get_pos_profile(self.company) or {}
		if not pos_profile:
			return
		self.pos_profile = pos_profile.get("name")

	pos = {}
	if self.pos_profile:
		pos = frappe.get_doc("POS Profile", self.pos_profile)

	if pos:
		if not for_validate:
			update_multi_mode_option(self, pos)
			self.tax_category = pos.get("tax_category")

		if not for_validate and not self.customer:
			self.customer = pos.customer

		if not for_validate:
			self.ignore_pricing_rule = pos.ignore_pricing_rule

		if pos.get("account_for_change_amount"):
			self.account_for_change_amount = pos.get("account_for_change_amount")

		for fieldname in (
			"currency",
			"letter_head",
			"tc_name",
			"company",
			"select_print_heading",
			"write_off_account",
			"taxes_and_charges",
			"write_off_cost_center",
			"apply_discount_on",
			"cost_center",
		):
			if (not for_validate) or (for_validate and not self.get(fieldname)):
				self.set(fieldname, pos.get(fieldname))

		if pos.get("company_address"):
			self.company_address = pos.get("company_address")

		if self.customer:
			customer_price_list, customer_group = frappe.get_value(
				"Customer", self.customer, ["default_price_list", "customer_group"]
			)
			customer_group_price_list = frappe.get_value(
				"Customer Group", customer_group, "default_price_list"
			)
			selling_price_list = (
				customer_price_list or customer_group_price_list or pos.get("selling_price_list")
			)
		else:
			selling_price_list = pos.get("selling_price_list")

		if selling_price_list:
			self.set("selling_price_list", selling_price_list)

		# set pos values in items
		for item in self.get("items"):
			if item.get("item_code"):
				profile_details = get_pos_profile_item_details_(
					ItemDetailsCtx(item.as_dict()), pos, pos, update_data=True
				)
				for fname, val in profile_details.items():
					if (not for_validate) or (for_validate and not item.get(fname)):
						item.set(fname, val)

		if not for_validate:
			dn_flag = any(d.get("dn_detail") for d in self.get("items"))
			self.update_stock = 0 if dn_flag else cint(pos.get("update_stock"))

		# fetch terms
		if self.tc_name and not self.terms:
			self.terms = frappe.db.get_value("Terms and Conditions", self.tc_name, "terms")

		# fetch charges
		if self.taxes_and_charges and not len(self.get("taxes")):
			self.set_taxes()

	return pos

def validate_debit_to_acc(self):
	if not self.debit_to:
		self.debit_to = get_party_account("Customer", self.customer, self.company)
		if not self.debit_to:
			self.raise_missing_debit_credit_account_error("Customer", self.customer)

	account = frappe.get_cached_value(
		"Account", self.debit_to, ["account_type", "report_type", "account_currency"], as_dict=True
	)

	if not account:
		frappe.throw(_("Debit To is required"), title=_("Account Missing"))

	if account.report_type != "Balance Sheet":
		msg = (
			_("Please ensure {} account is a Balance Sheet account.").format(frappe.bold(_("Debit To")))
			+ " "
		)
		msg += _(
			"You can change the parent account to a Balance Sheet account or select a different account."
		)
		frappe.throw(msg, title=_("Invalid Account"))

	if self.customer and account.account_type != "Receivable":
		msg = (
			_("Please ensure {} account {} is a Receivable account.").format(
				frappe.bold(_("Debit To")), frappe.bold(self.debit_to)
			)
			+ " "
		)
		msg += _("Change the account type to Receivable or select a different account.")
		frappe.throw(msg, title=_("Invalid Account"))

	self.party_account_currency = account.account_currency

