			},
			"Sales Order Item": {
				"ref_dn_field": "so_detail",
				"compare_fields": [["item_code", "="], ["uom", "="], ["conversion_factor", "="]],
				"is_child_table": True,
				"allow_duplicate_prev_row_id": True,
			},
			"Delivery Note": {
				"ref_dn_field": "delivery_note",
				"compare_fields": [
					["customer", "="],
					["company", "="],
					["project", "="],
					["currency", "="],
				],
			},
			"Delivery Note Item": {
				"ref_dn_field": "dn_detail",
				"compare_fields": [["item_code", "="], ["uom", "="], ["conversion_factor", "="]],
				"is_child_table": True,
				"allow_duplicate_prev_row_id": True,
			},
		}
	)

	if (
		cint(frappe.get_single_value("Selling Settings", "maintain_same_sales_rate"))
		and not self.is_return
		and not self.is_internal_customer
	):
		self.validate_rate_with_reference_doc(
			[["Sales Order", "sales_order", "so_detail"], ["Delivery Note", "delivery_note", "dn_detail"]]
		)

def validate_closed_delivery_notes(self):
	delivery_notes = {d.delivery_note for d in self.items if d.delivery_note}
	if self.is_return or not delivery_notes:
		return

	if closed := frappe.get_all(
		"Delivery Note", filters={"name": ("in", list(delivery_notes)), "status": "Closed"}, pluck="name"
	):
		frappe.throw(
			_("Delivery Note {0} is closed and cannot be invoiced").format(
				", ".join(frappe.bold(name) for name in closed)
			)
		)

def validate_delivery_note_rows_billed_by_invoice(self):
	dn_details = [d.dn_detail for d in self.items if d.dn_detail]
	if self.is_return or not dn_details:
		return

	billing_invoices = frappe._dict(
		frappe.get_all(
			"Delivery Note Item",
			filters={"name": ("in", dn_details), "against_sales_invoice": ("is", "set")},
			fields=["name", "against_sales_invoice"],
			as_list=True,
		)
	)
	for d in self.items:
		invoice = billing_invoices.get(d.dn_detail)
		if invoice and invoice != self.name:
			frappe.throw(
				_(
					"Row #{0}: Delivery Note {1} was created from Sales Invoice {2}, which already bills it"
				).format(d.idx, frappe.bold(d.delivery_note), get_link_to_form("Sales Invoice", invoice))
			)

def set_against_income_account(self):
	"""Set against account for debit to account"""
	against_acc = []
	for d in self.get("items"):
		if d.income_account and d.income_account not in against_acc:
			against_acc.append(d.income_account)
	self.against_income_account = ",".join(against_acc)

def force_set_against_income_account(self):
	self.set_against_income_account()
	frappe.db.set_value(self.doctype, self.name, "against_income_account", self.against_income_account)

def add_remarks(self):
	if not self.remarks:
		if self.po_no:
			self.remarks = _("Against Customer Order {0}").format(self.po_no)
			if self.po_date:
				self.remarks += " " + _("dated {0}").format(formatdate(self.po_date))

def validate_auto_set_posting_time(self):
	# Don't auto set the posting date and time if invoice is amended
	if self.is_new() and self.amended_from:
		self.set_posting_time = 1

	self.validate_posting_time()

def so_dn_required(self):
	"""check in manage account if sales order / delivery note required or not."""
	if self.is_return:
		return

	prev_doc_field_map = {
		"Sales Order": ["so_required", "is_pos"],
		"Delivery Note": ["dn_required", "update_stock"],
	}
	for key, value in prev_doc_field_map.items():
		if frappe.get_single_value("Selling Settings", value[0]) == "Yes":
			if frappe.get_value("Customer", self.customer, value[0]):
				continue

			for d in self.get("items"):
				if d.item_code and not d.get(key.lower().replace(" ", "_")) and not self.get(value[1]):
					msgprint(
						_("{0} is mandatory for Item {1}").format(key, d.item_code), raise_exception=1
					)

def validate_proj_cust(self):
	"""check for does customer belong to same project as entered.."""
	if self.project and self.customer:
		res = frappe.db.sql(
			"""select name from `tabProject`
			where name = %s and (customer = %s or customer is null or customer = '')""",
			(self.project, self.customer),
		)
		if not res:
			throw(_("Customer {0} does not belong to project {1}").format(self.customer, self.project))

def validate_pos(self):
	# Consolidation posts payments already accepted on submitted POS invoices.
	if not self.get("is_consolidated"):
		for payment in self.get("payments") or []:
			validate_enabled_mode_of_payment(payment.mode_of_payment)

	if self.is_return:
		invoice_total = self.rounded_total or self.grand_total
		if abs(flt(self.paid_amount)) + abs(flt(self.write_off_amount)) - abs(
			flt(invoice_total)
		) > 1.0 / (10.0 ** (self.precision("grand_total") + 1.0)):
			frappe.throw(_("Paid amount + Write Off Amount can not be greater than Grand Total"))

def validate_created_using_pos(self):
	if self.is_created_using_pos and not self.pos_profile:
		frappe.throw(_("POS Profile is mandatory to mark this invoice as POS Transaction."))

	self.invoice_type_in_pos = frappe.db.get_single_value("POS Settings", "invoice_type")
	if self.invoice_type_in_pos == "POS Invoice" and not self.is_return:
		frappe.throw(_("Transactions using Sales Invoice in POS are disabled."))

	self.validate_pos_opening_entry()

def validate_full_payment(self):
	allow_partial_payment = frappe.db.get_value("POS Profile", self.pos_profile, "allow_partial_payment")
	invoice_total = flt(self.rounded_total) or flt(self.grand_total)

	if (
		self.docstatus == 1
		and not self.is_return
		and not allow_partial_payment
		and self.paid_amount < invoice_total
	):
		frappe.throw(
			msg=_("Partial Payment in POS Transactions are not allowed."),
			exc=PartialPaymentValidationError,
		)

def validate_pos_opening_entry(self):
	opening_entries = frappe.get_all(
		"POS Opening Entry",
		fields=["name", "period_start_date"],
		filters={"pos_profile": self.pos_profile, "status": "Open"},
		order_by="period_start_date desc",
	)
	if not opening_entries:
		frappe.throw(
			title=_("POS Opening Entry Missing"),
			msg=_("No open POS Opening Entry found for POS Profile {0}.").format(
				frappe.bold(self.pos_profile)
			),
		)
	if len(opening_entries) > 1:
		frappe.throw(
			title=_("Multiple POS Opening Entry"),
			msg=_(
				"POS Profile - {0} has multiple open POS Opening Entries. Please close or cancel the existing entries before proceeding."
			).format(self.pos_profile),
		)
	if frappe.utils.get_date_str(opening_entries[0].get("period_start_date")) != frappe.utils.today():
		frappe.throw(
			title=_("Outdated POS Opening Entry"),
			msg=_(
				"POS Opening Entry - {0} is outdated. Please close the POS and create a new POS Opening Entry."
			).format(opening_entries[0].get("name")),
		)

def validate_warehouse(self):
	super().validate_warehouse()

	for d in self.get_item_list():
		if (
			not d.warehouse
			and d.item_code
			and frappe.get_cached_value("Item", d.item_code, "is_stock_item")
		):
			frappe.throw(_("Warehouse required for stock Item {0}").format(d.item_code))

def validate_delivery_note(self):
	"""If items are linked with a delivery note, stock cannot be updated again."""
	if not cint(self.update_stock):
		return

	notes = [item.delivery_note for item in self.items if item.delivery_note]
	if notes:
		frappe.throw(
			_("Stock cannot be updated against the following Delivery Notes: {0}").format(
				comma_and(notes)
			),
		)

def allow_write_off_only_on_pos(self):
	if not self.is_pos and self.write_off_account:
		self.write_off_account = None

def validate_subcontracted_sales_order(self):
	if self.has_subcontracted:
		if [item for item in self.items if not item.sales_order and not item.scio_detail]:
			frappe.throw(
				_(
					"All items must be linked to a Sales Order or Subcontracting Inward Order for this Sales Invoice."
				)
			)
		if not all(
			frappe.get_all(
				"Sales Order",
				{"name": ["in", [item.sales_order for item in self.items if item.sales_order]]},
				pluck="is_subcontracted",
			)
		):
			frappe.throw(_("All linked Sales Orders must be subcontracted."))

def validate_scio_self_rm_qty(self):
	self_rms = [item for item in self.items if item.scio_detail]
	if self_rms:
		stock_qty = self.get_scio_self_rm_stock_qty()
		table = frappe.qb.DocType("Subcontracting Inward Order Received Item")
		query = (
			frappe.qb.from_(table)
			.select(table.required_qty, table.consumed_qty, table.billed_qty, table.name)
			.where((table.docstatus == 1) & (table.name.isin(list(stock_qty))))
		)
		result = query.run(as_dict=True)
		data = {item.name: item for item in result}
		for item in self_rms:
			row = data.get(item.scio_detail)
			max_qty = max(row.required_qty, row.consumed_qty) - row.billed_qty
			if stock_qty[item.scio_detail] > max_qty:
				frappe.throw(
					_("Row #{0}: Stock quantity {1} ({2}) for item {3} cannot exceed {4}").format(
						item.idx,
						stock_qty[item.scio_detail],
						item.stock_uom,
						get_link_to_form("Item", item.item_code),
						frappe.bold(max_qty),
					)
				)

def validate_write_off_account(self):
	if flt(self.write_off_amount) and not self.write_off_account:
		self.write_off_account = frappe.get_cached_value("Company", self.company, "write_off_account")

	if flt(self.write_off_amount) and not self.write_off_account:
		msgprint(_("Please enter Write Off Account"), raise_exception=1)

def validate_account_for_change_amount(self):
	if flt(self.change_amount) and not self.account_for_change_amount:
		msgprint(_("Please enter Account for Change Amount"), raise_exception=1)

def validate_dropship_item(self):
	"""If items are drop shipped, stock cannot be updated."""
	if not cint(self.update_stock):
		return

	if any(item.delivered_by_supplier for item in self.items):
		frappe.throw(
			_(
				"Stock cannot be updated because the invoice contains a drop shipping item. Please disable 'Update Stock' or remove the drop shipping item."
			),
		)

def update_current_stock(self):
	for item in self.items:
		item.set_actual_qty()

	for packed_item in self.packed_items:
		packed_item.set_actual_and_projected_qty()

def update_packing_list(self):
	if cint(self.update_stock) == 1:
		from erpnext.stock.doctype.packed_item.packed_item import make_packing_list

		make_packing_list(self)
	else:
		self.set("packed_items", [])

def set_billing_hours_and_amount(self):
	"""Fill rows from their time logs; a row without one gets its timesheet's unbilled logs."""
	if self.is_return:
		return

	pending = [
		row
		for row in self.timesheets
		if row.time_sheet and not (row.timesheet_detail and row.billing_hours and row.billing_amount)
	]
	unbilled_logs = {
		name: get_projectwise_timesheet_data(self.project, name)
		for name in {row.time_sheet for row in pending}
	}
	exchange_rates = {}
	for row in pending:
		if row.timesheet_detail:
			self.fill_from_time_log(row, unbilled_logs[row.time_sheet], exchange_rates)
		else:
			self.replace_with_time_logs(row, unbilled_logs[row.time_sheet], exchange_rates)

def fill_from_time_log(self, row, time_logs: list, exchange_rates: dict):
	if log := next((log for log in time_logs if log.name == row.timesheet_detail), None):
		row.billing_hours = row.billing_hours or log.billing_hours
		row.billing_amount = row.billing_amount or self.get_billing_amount(log, exchange_rates)

def replace_with_time_logs(self, row, time_logs: list, exchange_rates: dict):
	listed = {d.timesheet_detail for d in self.timesheets}
	time_logs = [log for log in time_logs if log.name not in listed]
	if not time_logs:
		frappe.throw(
			_("Row {0}: Timesheet {1} has no unbilled billable time logs").format(
				row.idx, frappe.bold(row.time_sheet)
			)
		)

	if row.billing_amount:
		self.link_time_log(row, time_logs)
		return

	self.remove(row)
	for log in time_logs:
		self.append("timesheets", self.get_timesheet_row(log, exchange_rates))

def link_time_log(self, row, time_logs: list):
	"""Bill a row's own amount against the only unbilled log of its timesheet."""
	if len(time_logs) > 1:
		frappe.throw(
			_("Row {0}: Select the time log of Timesheet {1} that this amount bills").format(
				row.idx, frappe.bold(row.time_sheet)
			)
		)

	row.timesheet_detail = time_logs[0].name
	row.billing_hours = row.billing_hours or time_logs[0].billing_hours

def update_timesheet_billing_for_project(self):
	if (
		not self.is_return
		and not self.timesheets
		and self.project
		and self.has_value_changed("project")
		and self.is_auto_fetch_timesheet_enabled()
	):
		self.add_timesheet_data()
	else:
		self.calculate_billing_amount_for_timesheet()

def add_timesheet_data(self):
	self.set("timesheets", [])
	if self.project:
		exchange_rates = {}
		for data in get_projectwise_timesheet_data(self.project):
			self.append("timesheets", self.get_timesheet_row(data, exchange_rates))

		self.calculate_billing_amount_for_timesheet()

def get_billing_amount(self, time_log, exchange_rates: dict) -> float:
	"""Time log billing amount in the invoice currency; `exchange_rates` keeps each rate for the pass."""
	if not time_log.currency or time_log.currency == self.currency:
		return time_log.billing_amount

	if time_log.currency not in exchange_rates:
		exchange_rate = get_exchange_rate(time_log.currency, self.currency, self.posting_date)
		if not exchange_rate:
			frappe.throw(
				_(
					"Unable to find exchange rate for {0} to {1} for key date {2}. Please create a Currency Exchange record manually."
				).format(time_log.currency, self.currency, self.posting_date)
			)
		exchange_rates[time_log.currency] = exchange_rate

	return flt(time_log.billing_amount) * exchange_rates[time_log.currency]

def calculate_billing_amount_for_timesheet(self):
	def timesheet_sum(field):
		return sum((ts.get(field) or 0.0) for ts in self.timesheets)

	self.total_billing_amount = timesheet_sum("billing_amount")
	self.total_billing_hours = timesheet_sum("billing_hours")

def get_warehouse(self):
	user_pos_profile = frappe.db.sql(
		"""select name, warehouse from `tabPOS Profile`
		where ifnull(user,'') = %s and company = %s""",
		(frappe.session["user"], self.company),
	)
	warehouse = user_pos_profile[0][1] if user_pos_profile else None

	if not warehouse:
		global_pos_profile = frappe.db.sql(
			"""select name, warehouse from `tabPOS Profile`
			where (user is null or user = '') and company = %s""",
			self.company,
		)

		if global_pos_profile:
			warehouse = global_pos_profile[0][1]
		elif not user_pos_profile:
			msgprint(_("POS Profile required to make POS Entry"), raise_exception=True)

	return warehouse

def set_income_account_for_fixed_assets(self):
	for item in self.items:
		item.set_income_account_for_fixed_asset(self.company)

def check_prev_docstatus(self):
	for d in self.get("items"):
		if (
			d.sales_order
			and frappe.db.get_value("Sales Order", d.sales_order, "docstatus", cache=True) != 1
		):
			frappe.throw(_("Sales Order {0} is not submitted").format(d.sales_order))

		if (
			d.delivery_note
			and frappe.db.get_value("Delivery Note", d.delivery_note, "docstatus", cache=True) != 1
		):
			throw(_("Delivery Note {0} is not submitted").format(d.delivery_note))

def split_asset_based_on_sale_qty(self):
	asset_qty_map = self.get_asset_qty()
	for asset, qty in asset_qty_map.items():
		if qty["actual_qty"] < qty["sale_qty"]:
			frappe.throw(
				_(
					"Sell quantity cannot exceed the asset quantity. Asset {0} has only {1} item(s)."
				).format(asset, qty["actual_qty"])
			)

		remaining_qty = qty["actual_qty"] - qty["sale_qty"]
		if remaining_qty > 0:
			split_asset(asset, remaining_qty)

def get_asset_qty(self):
	asset_qty_map = {}

	assets = {row.asset for row in self.items if row.is_fixed_asset and row.asset}
	if not assets or self.is_return:
		return asset_qty_map

	asset_actual_qty = dict(
		frappe.db.get_all(
			"Asset",
			{"name": ["in", list(assets)]},
			["name", "asset_quantity"],
			as_list=True,
		)
	)
	for row in self.items:
		if row.is_fixed_asset and row.asset:
			actual_qty = asset_actual_qty.get(row.asset)
			if row.asset in asset_qty_map.keys():
				asset_qty_map[row.asset]["sale_qty"] += flt(row.qty)
			else:
				asset_qty_map.setdefault(
					row.asset,
					{
						"sale_qty": flt(row.qty),
						"actual_qty": flt(actual_qty),
					},
				)

	return asset_qty_map

def process_asset_depreciation(self):
	if self.is_internal_transfer():
		return

	if (self.is_return and self.docstatus == 2) or (not self.is_return and self.docstatus == 1):
		self.depreciate_asset_on_sale()
	else:
		self.restore_asset()

	self.update_asset()

def depreciate_asset_on_sale(self):
	"""
	Depreciate asset on sale or cancellation of return sales invoice
	"""
	disposal_date = self.get_disposal_date()
	for d in self.get("items"):
		if d.asset:
			asset = frappe.get_doc("Asset", d.asset)
			if asset.calculate_depreciation and asset.status != "Fully Depreciated":
				depreciate_asset(asset, disposal_date, self.get_note_for_asset_sale(asset))

def get_note_for_asset_sale(self, asset):
	return _("This schedule was created when Asset {0} was {1} through Sales Invoice {2}.").format(
		get_link_to_form(asset.doctype, asset.name),
		_("returned") if self.is_return else _("sold"),
		get_link_to_form(self.doctype, self.get("name")),
	)

def restore_asset(self):
	"""
	Restore asset on return or cancellation of original sales invoice
	"""

	for d in self.get("items"):
		if d.asset:
			asset = frappe.get_cached_doc("Asset", d.asset)
			if asset.calculate_depreciation:
				reverse_depreciation_entry_made_on_disposal(asset)

				note = self.get_note_for_asset_return(asset)
				reset_depreciation_schedule(asset, note)

def get_note_for_asset_return(self, asset):
	asset_link = get_link_to_form(asset.doctype, asset.name)
	invoice_link = get_link_to_form(self.doctype, self.get("name"))
	if self.is_return:
		return _(
			"This schedule was created when Asset {0} was returned through Sales Invoice {1}."
		).format(asset_link, invoice_link)
	else:
		return _(
			"This schedule was created when Asset {0} was restored due to Sales Invoice {1} cancellation."
		).format(asset_link, invoice_link)

def update_asset(self):
	"""
	Update asset status, disposal date and asset activity on sale or return sales invoice
	"""

	def _update_asset(asset, disposal_date, note, asset_status=None):
		frappe.db.set_value("Asset", d.asset, "disposal_date", disposal_date)
		add_asset_activity(asset.name, note)
		asset.set_status(asset_status)

	disposal_date = self.get_disposal_date()
	for d in self.get("items"):
		if d.asset:
			asset = frappe.get_cached_doc("Asset", d.asset)

			if (self.is_return and self.docstatus == 1) or (not self.is_return and self.docstatus == 2):
				note = _("Asset returned") if self.is_return else _("Asset sold")
				asset_status, disposal_date = None, None
			else:
				note = _("Asset sold") if not self.is_return else _("Return invoice of asset cancelled")
				asset_status = "Sold"

			_update_asset(asset, disposal_date, note, asset_status)

def get_disposal_date(self):
	if self.is_return:
		disposal_date = frappe.db.get_value("Sales Invoice", self.return_against, "posting_date")
	else:
		disposal_date = self.posting_date

	return disposal_date

def make_gl_entries(self, gl_entries=None, from_repost=False):
	from erpnext.accounts.general_ledger import make_gl_entries, make_reverse_gl_entries

	auto_accounting_for_stock = erpnext.is_perpetual_inventory_enabled(self.company)
	if not gl_entries:
		gl_entries = self.get_gl_entries()

	if gl_entries:
		# if POS and amount is written off, updating outstanding amt after posting all gl entries
		update_outstanding = (
			"No"
			if (cint(self.is_pos) or self.write_off_account or cint(self.redeem_loyalty_points))
			else "Yes"
		)

		if self.docstatus == 1:
			make_gl_entries(
				gl_entries,
				update_outstanding=update_outstanding,
				merge_entries=False,
				from_repost=from_repost,
			)

			self.make_exchange_gain_loss_journal()
		elif self.docstatus == 2:
			make_reverse_gl_entries(voucher_type=self.doctype, voucher_no=self.name)

		if update_outstanding == "No":
			update_voucher_outstanding(
				voucher_type=self.doctype,
				voucher_no=self.return_against
				if cint(self.is_return) and self.return_against
				else self.name,
				account=self.debit_to,
				party_type="Customer",
				party=self.customer,
			)

	elif self.docstatus == 2 and cint(self.update_stock) and cint(auto_accounting_for_stock):
		make_reverse_gl_entries(voucher_type=self.doctype, voucher_no=self.name)

def make_customer_gl_entry(self, gl_entries):
	# Checked both rounding_adjustment and rounded_total
	# because rounded_total had value even before introduction of posting GLE based on rounded total
	grand_total = (
		self.rounded_total if (self.rounding_adjustment and self.rounded_total) else self.grand_total
	)
	base_grand_total = flt(
		self.base_rounded_total
		if (self.base_rounding_adjustment and self.base_rounded_total)
		else self.base_grand_total,
		self.precision("base_grand_total"),
	)

	if grand_total and not self.is_internal_transfer():
		against_voucher = self.name
		if self.is_return and self.return_against and not self.update_outstanding_for_self:
			against_voucher = self.return_against

		# Did not use base_grand_total to book rounding loss gle
		gl_entries.append(
			self.get_gl_dict(
				{
					"account": self.debit_to,
					"party_type": "Customer",
					"party": self.customer,
					"due_date": self.due_date,
					"against": self.against_income_account,
					"debit": base_grand_total,
					"debit_in_account_currency": base_grand_total
					if self.party_account_currency == self.company_currency
					else grand_total,
					"debit_in_transaction_currency": grand_total,
					"against_voucher": against_voucher,
					"against_voucher_type": self.doctype,
					"cost_center": self.cost_center,
					"project": self.project,
				},
				self.party_account_currency,
				item=self,
			)
		)

def make_tax_gl_entries(self, gl_entries):
	enable_discount_accounting = cint(
		frappe.get_single_value("Selling Settings", "enable_discount_accounting")
	)

	for tax in self.get("taxes"):
		amount, base_amount = self.get_tax_amounts(tax, enable_discount_accounting)

		if flt(tax.base_tax_amount_after_discount_amount):
			account_currency = get_account_currency(tax.account_head)
			gl_entries.append(
				self.get_gl_dict(
					{
						"account": tax.account_head,
						"against": self.customer,
						"credit": flt(base_amount, tax.precision("tax_amount_after_discount_amount")),
						"credit_in_account_currency": (
							flt(base_amount, tax.precision("base_tax_amount_after_discount_amount"))
							if account_currency == self.company_currency
							else flt(amount, tax.precision("tax_amount_after_discount_amount"))
						),
						"credit_in_transaction_currency": flt(
							amount, tax.precision("tax_amount_after_discount_amount")
						),
						"cost_center": tax.cost_center,
					},
					account_currency,
					item=tax,
				)
			)

def make_internal_transfer_gl_entries(self, gl_entries):
	if self.is_internal_transfer() and flt(self.base_total_taxes_and_charges):
		account_currency = get_account_currency(self.unrealized_profit_loss_account)
		gl_entries.append(
			self.get_gl_dict(
				{
